package io.github.ningpp.compat;

/**
 * Replacement for System.Buffers.SequencePosition (generated by CSharpToJava converter).
 * The multi-segment sequence model is not simulated; positions are opaque tokens.
 */
public final class SequencePosition {
    private final Object segment;
    private final int index;

    public SequencePosition() {
        this.segment = null;
        this.index = 0;
    }

    public SequencePosition(Object segment, int index) {
        this.segment = segment;
        this.index = index;
    }

    /** Mirrors SequencePosition.GetInteger(). */
    public int getInteger() {
        return index;
    }

    /** Mirrors SequencePosition.GetObject(). */
    public Object getObject() {
        return segment;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) {
            return true;
        }
        if (!(obj instanceof SequencePosition other)) {
            return false;
        }
        return index == other.index && java.util.Objects.equals(segment, other.segment);
    }

    @Override
    public int hashCode() {
        return java.util.Objects.hash(segment, index);
    }
}
